import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"戚氏·晚秋天","description":"","frontmatter":{"title":"戚氏·晚秋天","date":"2026-11-16T00:00:00.000Z","seq":149,"categories":["美文","宋词三百首"],"collection":"《宋词三百首》","tags":["宋词三百首","宋"],"poem":true,"poem_quote":false,"author":"柳永","source_book":"宋词三百首","prev":{"text":"少年游·长安古道马迟","link":"/blogs/宋词三百首/少年游·长安古道马迟.html"},"next":{"text":"夜半乐·冻云黯淡天气","link":"/blogs/宋词三百首/夜半乐·冻云黯淡天气.html"}},"headers":[],"relativePath":"blogs/宋词三百首/戚氏·晚秋天.md","filePath":"blogs/宋词三百首/戚氏·晚秋天.md"}'),o={name:"blogs/宋词三百首/戚氏·晚秋天.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="戚氏·晚秋天" tabindex="-1">戚氏·晚秋天 <a class="header-anchor" href="#戚氏·晚秋天" aria-label="Permalink to &quot;戚氏·晚秋天&quot;">​</a></h1><p class="poem-meta">宋 · 柳永</p><div class="poem"><p class="poem-stanza">晚秋天。</p><p class="poem-stanza">一霎微雨洒庭轩。</p><p class="poem-stanza">槛菊萧疏，井梧零乱惹残烟。</p><p class="poem-stanza">凄然。</p><p class="poem-stanza">望江关。</p><p class="poem-stanza">飞云黯淡夕阳间。</p><p class="poem-stanza">当时宋玉悲感，向此临水与登山。</p><p class="poem-stanza">远道迢递，行人凄楚，倦听陇水潺。</p><p class="poem-stanza">正蝉吟败叶，蛩响衰草，相应喧喧。</p><p class="poem-stanza">孤馆度日如年。</p><p class="poem-stanza">风露渐变，悄悄至更阑。</p><p class="poem-stanza">长天净，绛河清浅，皓月婵娟。</p><p class="poem-stanza">思绵绵。</p><p class="poem-stanza">夜永对景，那堪屈指，暗想从前。</p><p class="poem-stanza">未名未禄，绮陌红楼，往往经岁迁延。</p><p class="poem-stanza">帝里风光好，当年少日，暮宴朝欢。</p><p class="poem-stanza">况有狂朋怪侣，遇当歌、对酒竞留连。</p><p class="poem-stanza">别来迅景如梭，旧游似梦，烟水程何限。</p><p class="poem-stanza">念利名、憔悴长萦绊。</p><p class="poem-stanza">追往事、空惨愁颜。</p><p class="poem-stanza">漏箭移、稍觉轻寒。</p><p class="poem-stanza">渐呜咽、画角数声残。</p><p class="poem-stanza">对闲窗畔，停灯向晓，抱影无眠。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
